<?php
declare(strict_types=1);
use Nexus\Application\Prestamo\PrestamoService;use Nexus\Application\Servicio\ServicioService;use Nexus\Domain\Prestamo\PrestamoRepository;use Nexus\Domain\Servicio\ServicioRepository;use Nexus\Domain\ValueObject\Cedula;
require_once __DIR__.'/../proyecto 3ra entrega/src/autoload.php';
final class PrestamosMemoria implements PrestamoRepository
{
    public array $filas=[];public function listar(Cedula $u,bool $g):array{return array_values(array_filter($this->filas,fn($f)=>$f['esta_activo']&&($g||$f['cedula']===$u->value())));}public function diasMaximos():int{return 30;}
    public function crear(array $d,Cedula $u):array{$ids=[];foreach($d['recursos'] as $r){$id=count($this->filas)+1;$this->filas[$id]=['id_prestamo'=>$id,'categoria'=>$d['categoria'],'estado'=>'Solicitado','fecha_solicitado'=>date('Y-m-d'),'fecha_devolucion'=>$d['fecha'],'recursos_solicitados'=>$r['descripcion'],'jornada'=>$d['jornada'],'lugar_entrega'=>$d['ubicacion'],'descripcion'=>$d['detalle'],'comentario_resolucion'=>null,'cedula'=>$u->value(),'nombre'=>'Jean','apellido'=>'Ortiz','id_equipo'=>$r['idEquipo'],'nombre_equipo'=>'Equipo','esta_activo'=>1];$ids[]=$id;}return $ids;}
    public function baja(int $id,Cedula $responsable):bool{if(!isset($this->filas[$id])||!$this->filas[$id]['esta_activo'])return false;$this->filas[$id]['esta_activo']=0;$this->filas[$id]['estado']='Cancelado';return true;}public function comentar(int $id,string $c,Cedula $responsable):bool{if(!isset($this->filas[$id])||!in_array($this->filas[$id]['estado'],['Activo','Devuelto','Cancelado'],true)||$this->filas[$id]['comentario_resolucion']!==null)return false;$this->filas[$id]['comentario_resolucion']=$c;return true;}public function cambiarEstado(int $id,string $e,Cedula $responsable,string $observacion=''):bool{if(!isset($this->filas[$id]))return false;$actual=$this->filas[$id]['estado'];$permitidas=['Solicitado'=>['Activo','Cancelado'],'Activo'=>['Devuelto'],'Devuelto'=>[],'Cancelado'=>[]];if(!in_array($e,$permitidas[$actual]??[],true))throw new \Nexus\Shared\DomainException('Transicion no permitida.',409);$this->filas[$id]['estado']=$e;if($e==='Devuelto')$this->filas[$id]['fecha_devolucion_real']=date('Y-m-d H:i:s');return true;}
}
final class ServiciosMemoria implements ServicioRepository
{
    public array $filas=[];public function listar(Cedula $u,bool $g):array{return array_values(array_filter($this->filas,fn($f)=>$f['esta_activo']&&($g||$f['cedula']===$u->value())));}public function usuarioExiste(Cedula $u):bool{return $u->value()==='57324099';}public function crear(array $d,Cedula $u):int{$id=count($this->filas)+1;$this->filas[$id]=['id_servicio'=>$id,'tipo_de_servicio'=>$d['tipo'],'estado'=>'Pendiente','descripcion'=>$d['detalle'],'titulo'=>$d['titulo'],'lugar'=>$d['lugar'],'fecha_de_solicitud'=>date('Y-m-d'),'fecha_deseada'=>$d['fechaDeseada'],'cedula'=>$u->value(),'nombre_solicitante'=>'Jean','apellido_solicitante'=>'Ortiz','esta_activo'=>1];return $id;}public function baja(int $id):bool{if(!isset($this->filas[$id])||!$this->filas[$id]['esta_activo'])return false;$this->filas[$id]['esta_activo']=0;$this->filas[$id]['estado']='Cancelado';return true;}public function cambiarEstado(int $id,string $e):bool{if(!isset($this->filas[$id]))return false;$this->filas[$id]['estado']=$e;return true;}
}
function assertO(bool $c,string $m):void{if(!$c)throw new RuntimeException($m);}function rechazaO(callable $accion,string $m):void{try{$accion();}catch(\Nexus\Shared\DomainException){return;}throw new RuntimeException($m);}$u=new Cedula('57324099');$pr=new PrestamosMemoria();$p=new PrestamoService($pr);$fecha=(new DateTimeImmutable('+5 days'))->format('Y-m-d');
$alta=$p->crear(['fecha'=>$fecha,'recursos'=>[['idEquipo'=>1,'nombre'=>'Notebook Dell Latitude','cantidad'=>2],['idEquipo'=>2,'nombre'=>'Proyector Epson','cantidad'=>1]],'categoria'=>'Equipamiento','jornada'=>'Mañana','ubicacion'=>'Laboratorio 1','detalle'=>'Clase de programación'],$u);assertO(count($alta['ids'])===2,'No creó todos los recursos.');
$p->cambiarEstado(1,'Aprobado',$u);$p->comentar(1,'Préstamo entregado correctamente.',$u);assertO($pr->filas[1]['estado']==='Activo'&&$pr->filas[1]['comentario_resolucion']!=='','No atendió/comentó préstamo.');rechazaO(fn()=>$p->comentar(1,'Comentario duplicado.',$u),'Permitió sobrescribir el comentario del préstamo.');$p->cambiarEstado(1,'Devuelto',$u);assertO($pr->filas[1]['estado']==='Devuelto'&&!empty($pr->filas[1]['fecha_devolucion_real']),'No registró la devolución real.');rechazaO(fn()=>$p->cambiarEstado(1,'Aprobado',$u),'Permitió reabrir un préstamo devuelto.');$listado=$p->listar($u,false);assertO($listado[0]['cantidad']===2&&$listado[0]['recurso']==='Notebook Dell Latitude','No presentó cantidad/recurso.');$p->baja(2,$u);assertO(!$pr->filas[2]['esta_activo'],'No aplicó baja lógica.');
$sr=new ServiciosMemoria();$s=new ServicioService($sr);$id=$s->crear(['tipo'=>'Instalación','titulo'=>'Instalar IDE','lugar'=>'Laboratorio 1','detalle'=>'Instalar Visual Studio Code.','fechaDeseada'=>$fecha],$u);$s->cambiarEstado($id,'En proceso');assertO($sr->filas[$id]['estado']==='En proceso','No inició servicio.');$s->cambiarEstado($id,'Completado');assertO($s->listar($u,false)[0]['estado']==='Completado','No finalizó/presentó servicio.');$s->baja($id);assertO(!$sr->filas[$id]['esta_activo'],'No aplicó baja de servicio.');
rechazaO(fn()=>$s->crear(['tipo'=>'','titulo'=>'','lugar'=>'','detalle'=>'','fechaDeseada'=>$fecha],$u),'Aceptó un servicio sin datos obligatorios.');
rechazaO(fn()=>$s->crear(['tipo'=>'Instalación','titulo'=>'Instalar IDE','lugar'=>'Laboratorio 1','detalle'=>'Preparar el equipo.','fechaDeseada'=>(new DateTimeImmutable('-1 day'))->format('Y-m-d')],$u),'Aceptó una fecha deseada anterior a hoy.');
